{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C38"],
      "claim": "Morphine, the closest analogue (Morgan 0.541), has average oral bioavailability of 20–30% in healthy volunteers and cancer patients, placing it at/above the 20% threshold and supporting high F for the closely related hydromorphone scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Morphine-d3, a close morphinan analogue, showed oral bioavailability of 37.2 ± 10.2% in opioid-dependent patients, directly supporting F ≥20% for this scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "Codeine, a 3-methoxy morphinan, has oral bioavailability of 84 ± 5%, demonstrating that morphinans can achieve high oral F; hydromorphone's 6-keto modification increases lipophilicity relative to morphine.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Nalmefene, a 6-keto morphinan antagonist, has absolute oral bioavailability of 41%, supporting high F for a 6-keto morphinan.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Naltrexone shows ~5% oral bioavailability, but this low-F evidence transfers poorly because hydromorphone lacks naltrexone's 14-hydroxy and N-cyclopropylmethyl substituents that drive extensive first-pass metabolism.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C39"],
      "claim": "M6G has poor oral bioavailability, but as a polar glucuronide conjugate it is not representative of the lipophilic hydromorphone molecule.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Hydromorphone is predicted to have F ≥20% even under rifampin co-treatment. Most transferable morphinan evidence (morphine 20-30%, morphine-d3 37%, codeine 84%, nalmefene 41%) supports high oral bioavailability; low-F analogues (naltrexone, M6G) are structurally dissimilar. Rifampin may induce first-pass metabolism/efflux, but the baseline F of hydromorphone is expected to be well above 20%, and no evidence indicates a reduction below threshold.",
  "evidence_gaps": [
    "No direct experimental record for hydromorphone under rifampin co-treatment; the rifampin effect is inferred from enzyme induction and analogue data.",
    "Morphine evidence is borderline around 20-30%, so a substantial rifampin-mediated reduction could theoretically cross the threshold."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

